<?php require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['category_name']??'');if(strlen($name)<2)$error='Category name is too short.';elseif(db_one('SELECT id FROM categories WHERE category_name=?','s',[$name]))$error='That category already exists.';else{$stmt=db()->prepare('INSERT INTO categories (category_name) VALUES (?)');$stmt->bind_param('s',$name);$stmt->execute();flash('success','Category added.');redirect('admin/categories.php');}}$categories=db_all('SELECT ca.*,COUNT(c.id) complaint_count FROM categories ca LEFT JOIN complaints c ON c.category_id=ca.id GROUP BY ca.id ORDER BY ca.category_name');$pageTitle='Categories';require_once __DIR__.'/../includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-3"><?php require __DIR__.'/_sidebar.php'; ?></div><div class="col-lg-9"><div class="dashboard-header mb-4"><div class="small-muted">ADMINISTRATION</div><h1 class="section-title mb-0">Complaint categories</h1></div><div class="card mb-4"><div class="card-body"><form class="row g-2"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="col-md-9"><input class="form-control" name="category_name" placeholder="Add a new category" required></div><div class="col-md-3"><button class="btn btn-primary w-100">Add category</button></div></form><?php if($error): ?><div class="text-danger mt-2"><?=e($error)?></div><?php endif;?></div></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Category</th><th>Complaints</th><th>Created</th></tr></thead><tbody><?php foreach($categories as $row): ?><tr><td class="fw-semibold"><?=e($row['category_name'])?></td><td><?= (int)$row['complaint_count'] ?></td><td class="small-muted"><?=e(date('d M Y',strtotime($row['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
